    bgc=Counter(x for r in I for x in r).most_common(1)[0][0]
    H,W=len(I),len(I[0])
    out=[row[:] for row in I]
    cl=compso(I,bgc)
    # normalize each comp; find groups sharing normcol among comps
    groups=defaultdict(list)
    for cc in cl: groups[normcol(cc,I)].append(cc)
    for pat,lst in groups.items():
        if len(lst)<2: continue
        D=dict(((y,x),v) for y,x,v in pat)
        th=max(y for y,x,v in pat)+1; tw=max(x for y,x,v in pat)+1
        placed=[]
        used=set()
        while len(placed)<len(lst):
            best=None
            for r in range(H-th+1):
                for c in range(W-tw+1):
                    ok=True
                    for y,x,v in pat:
                        rr,cc=r+y,c+x
                        if I[rr][cc]!=bgc and I[rr][cc]!=v: ok=False;break
                    if not ok: continue
                    painted=sum(1 for y,x,v in pat if I[r+y][c+x]==bgc)
                    key=(painted,)
                    if best is None or key>best[0]: best=(key,(r,c))
            if best: placed.append(best[1]); used.add(tuple(best[1]))
        # stamp
        for (r,c) in placed:
            for y,x,v in pat:
                if out[r+y][c+x]==bgc: out[r+y][c+x]=v
    return out
